-- =====================================================================
-- Add public share link support to itineraries.
--
-- public_link_id: a short, unique, random token (generated by the app)
--                 that lets anyone with the link view the itinerary.
-- is_link_shared: toggled true when the owner enables the public link.
--
-- RLS: anon users (no auth token) can SELECT rows where is_link_shared = true.
--      They cannot INSERT, UPDATE, or DELETE.
-- =====================================================================

ALTER TABLE public.itineraries
  ADD COLUMN IF NOT EXISTS public_link_id   TEXT UNIQUE,
  ADD COLUMN IF NOT EXISTS is_link_shared   BOOLEAN NOT NULL DEFAULT false;

-- Index for fast public-link lookups
CREATE INDEX IF NOT EXISTS idx_itineraries_public_link_id
  ON public.itineraries (public_link_id)
  WHERE public_link_id IS NOT NULL;

-- ── RLS policy: allow anon to read publicly-shared itineraries ────────
-- The existing "Users can view their own itineraries" policy already
-- covers authenticated users.  This new policy adds read access for
-- anyone (including unauthenticated visitors) when is_link_shared = true.

DROP POLICY IF EXISTS "Public link: anon can view shared itineraries" ON public.itineraries;

CREATE POLICY "Public link: anon can view shared itineraries"
  ON public.itineraries
  FOR SELECT
  USING (is_link_shared = true);

-- ── Allow anon SELECT on related tables for the public view ──────────
-- itinerary_items (activities)
DROP POLICY IF EXISTS "Public link: anon can view items of shared itineraries" ON public.itinerary_items;

CREATE POLICY "Public link: anon can view items of shared itineraries"
  ON public.itinerary_items
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.itineraries i
      WHERE i.id = itinerary_items.itinerary_id
        AND i.is_link_shared = true
    )
  );

-- cities (needed for city name / image on the public view)
-- cities table is likely already readable; add a permissive policy if missing
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'cities'
      AND policyname = 'Public: anyone can read cities'
  ) THEN
    EXECUTE 'CREATE POLICY "Public: anyone can read cities" ON public.cities FOR SELECT USING (true)';
  END IF;
END $$;
